def compute(vars):
    actual = vars["v1"]
    target = vars["v2"]
    if target == 0:
        return None
    value = actual / target
    return {
        "value": value,
        "trace": {
            "actual": actual,
            "target": target,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio"
            }
        }
    }
